/// Depth-coded vertex fill (req_3064): from an axis-on view every dot lands on the same
/// pixel column and coplanarity is unreadable, so the FILL encodes depth along the view's
/// dominant WORLD axis — verts at the exact same depth share the exact same colour, and
/// one off-plane vert reads as the odd colour out. The hue wheel cycles once per
/// OV_DEPTH_HUE_PERIOD_M of depth, so a
/// centimetre of drift becomes a ~14° hue step instead of an invisible fraction of the
/// mesh's whole depth range. Cyclic aliasing (two planes 25 cm apart sharing a hue) is
/// fine — the comparison is always between neighbours expected coplanar.
pub const OV_DEPTH_HUE_PERIOD_M: f32 = 0.25;
pub fn ovDepthColor(depth: f32) [3]f32 {
    return effects_ctx.EffectContext.hsvToRgb(depth / z3d.OV_DEPTH_HUE_PERIOD_M, 0.65, 1.0);
}
/// A haloed dot: a dark disc, then the bright fill on top — visible on any background.
pub fn overlayDot(px: f32, py: f32, r: f32, g: f32, b: f32, size: f32) void {
    core.drawCapsule(px, py, px, py, z3d.OV_HALO[0], z3d.OV_HALO[1], z3d.OV_HALO[2], z3d.OV_HALO[3], size + 3.5);
    core.drawCapsule(px, py, px, py, r, g, b, 1.0, size);
}
/// A haloed line — dark stroke under a bright one, so selected edges read on any surface.
pub fn overlayLine(ax: f32, ay: f32, bx: f32, by: f32, r: f32, g: f32, b: f32, w: f32) void {
    core.drawCapsule(ax, ay, bx, by, z3d.OV_HALO[0], z3d.OV_HALO[1], z3d.OV_HALO[2], z3d.OV_HALO[3], w + 2.5);
    core.drawCapsule(ax, ay, bx, by, r, g, b, 1.0, w);
}

pub fn axisVec(axis: i32) [3]f32 {
    return switch (axis) {
        0 => .{ 1, 0, 0 },
        1 => .{ 0, 1, 0 },
        else => .{ 0, 0, 1 },
    };
}
pub fn axisColor(axis: i32) [3]f32 {
    return switch (axis) {
        0 => z3d.GIZMO_X,
        1 => z3d.GIZMO_Y,
        else => z3d.GIZMO_Z,
    };
}
pub fn vadd(a: [3]f32, b: [3]f32) [3]f32 {
    return .{ a[0] + b[0], a[1] + b[1], a[2] + b[2] };
}
pub fn vsub(a: [3]f32, b: [3]f32) [3]f32 {
    return .{ a[0] - b[0], a[1] - b[1], a[2] - b[2] };
}
pub fn vmul(a: [3]f32, s: f32) [3]f32 {
    return .{ a[0] * s, a[1] * s, a[2] * s };
}
pub fn vdot(a: [3]f32, b: [3]f32) f32 {
    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
}
pub fn vcross(a: [3]f32, b: [3]f32) [3]f32 {
    return .{ a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0] };
}
pub fn vnorm(a: [3]f32) [3]f32 {
    const l = @sqrt(z3d.vdot(a, a));
    if (l < 1e-8) return .{ 0, 0, 0 };
    return .{ a[0] / l, a[1] / l, a[2] / l };
}
