/// front view). Two honest arms beat three, one of which lies.
pub fn gizmoAxisGrabbable(s: z3d.AxisScreen, face_on_px_per_unit: f32) bool {
    return gizmo_axis_map.isGrabbable(s, face_on_px_per_unit);
}
/// A handle's screen position: GIZMO_ARM_PX along the axis' screen direction.
pub fn gizmoArmEnd(s: z3d.AxisScreen, sign: f32) [2]f32 {
    return .{ s.ax + s.dx * z3d.GIZMO_ARM_PX * sign, s.ay + s.dy * z3d.GIZMO_ARM_PX * sign };
}
pub fn segDist2(px: f32, py: f32, ax: f32, ay: f32, bx: f32, by: f32) f32 {
    const vx = bx - ax;
    const vy = by - ay;
    const wx = px - ax;
    const wy = py - ay;
    const len2 = vx * vx + vy * vy;
    const t = if (len2 > 1e-6) std.math.clamp((wx * vx + wy * vy) / len2, 0.0, 1.0) else 0.0;
    const cx = ax + t * vx;
    const cy = ay + t * vy;
    const dx = px - cx;
    const dy = py - cy;
    return dx * dx + dy * dy;
}
pub fn ringBasis(axis: [3]f32) [2][3]f32 {
    const ref: [3]f32 = if (@abs(axis[1]) < 0.85) .{ 0, 1, 0 } else .{ 1, 0, 0 };
    const u = z3d.vnorm(z3d.vcross(axis, ref));
    return .{ u, z3d.vnorm(z3d.vcross(axis, u)) };
}
/// Port of the studio's ringRadiusWorld: the world radius that projects to ~armPx at
/// the pivot, derived from the FIRST axis with a usable screen span (X unless X is
/// degenerate). Deliberately including the studio's quirk the user PINNED as a feature
/// (req_2827): when that axis foreshortens (the view swinging down it), px-per-unit
/// collapses and the rings BLOW UP on screen — a much larger wheel, so every dragged
/// pixel is a finer angle.
pub fn gizmoRingWorldR(cam: model_paint.Camera, pivot: [3]f32) f32 {
    var a: i32 = 0;
    while (a < 3) : (a += 1) {
        const s = z3d.axisScreenInfo(cam, pivot, z3d.axisVec(a)) orelse continue;
        if (s.px_per_unit > 1e-4) return z3d.GIZMO_ARM_PX / s.px_per_unit;
    }
    return 0;
}
pub fn drawGizmoRing(cam: model_paint.Camera, pivot: [3]f32, axis: i32, ox: f32, oy: f32) void {
    const col = z3d.gizmoAxisDrawColor(axis); // the grabbed ring glows gold (studio behavior)
    const av = z3d.axisVec(axis);
    const basis = z3d.ringBasis(av);
    const r = z3d.gizmoRingWorldR(cam, pivot);
    const steps: u32 = 48;
    var prev: ?[2]f32 = null;
    var i: u32 = 0;
    while (i <= steps) : (i += 1) {
        const t = (@as(f32, @floatFromInt(i)) / @as(f32, @floatFromInt(steps))) * std.math.pi * 2.0;
        const p = z3d.vadd(pivot, z3d.vadd(z3d.vmul(basis[0], @cos(t) * r), z3d.vmul(basis[1], @sin(t) * r)));
        const sp = model_paint.project(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, p) orelse {
            prev = null;
            continue;
        };
        if (prev) |q| z3d.overlayLine(q[0] + ox, q[1] + oy, sp[0] + ox, sp[1] + oy, col[0], col[1], col[2], 3.0);
        prev = sp;
    }
}
pub fn ringHitDist2(cam: model_paint.Camera, pivot: [3]f32, axis: i32, mx: f32, my: f32) f32 {
    const av = z3d.axisVec(axis);
    const basis = z3d.ringBasis(av);
    const r = z3d.gizmoRingWorldR(cam, pivot);
    const steps: u32 = 48;
    var prev: ?[2]f32 = null;
    var best: f32 = 1.0e12;
    var i: u32 = 0;
    while (i <= steps) : (i += 1) {
        const t = (@as(f32, @floatFromInt(i)) / @as(f32, @floatFromInt(steps))) * std.math.pi * 2.0;
        const p = z3d.vadd(pivot, z3d.vadd(z3d.vmul(basis[0], @cos(t) * r), z3d.vmul(basis[1], @sin(t) * r)));
        const sp = model_paint.project(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, p) orelse {
            prev = null;
            continue;
        };
        if (prev) |q| best = @min(best, z3d.segDist2(mx, my, q[0], q[1], sp[0], sp[1]));
        prev = sp;
    }
    return best;
}

/// Live mirror planes (req_2758): each enabled symmetry plane draws as an axis-colored
/// square outline through the shared model-origin plane — the standing signal that
/// edits on one side land on the other. Edit dressing: paint mode hides it.
pub fn drawMirrorPlanesOverlay(cam: model_paint.Camera, ox: f32, oy: f32) void {
    const mask = mesh_edit.mirrorMask();
    if (mask == 0) return;
    const frame = mesh_edit.mirrorFramePub() orelse return;
    const r = frame.radius;
    const center = frame.center;
    var axis: u3 = 0;
    while (axis < 3) : (axis += 1) {
        if (mask & (@as(u8, 1) << axis) == 0) continue;
        // The plane's rect spans the two OTHER axes at MIRROR_PLANE_CENTER, sized to
        // reach the scope's geometry.
        const b: u3 = if (axis == 0) 1 else 0;
        const cx: u3 = if (axis == 2) 1 else 2;
        var corners: [4][3]f32 = .{ center, center, center, center };
        const signs = [4][2]f32{ .{ -1, -1 }, .{ 1, -1 }, .{ 1, 1 }, .{ -1, 1 } };
        for (signs, 0..) |s, i| {
            corners[i][axis] = center[axis];
            corners[i][b] = center[b] + s[0] * r;
            corners[i][cx] = center[cx] + s[1] * r;
        }
        const col = z3d.axisColor(@intCast(axis));
        var i: usize = 0;
        while (i < 4) : (i += 1) {
            const pa = z3d.ovProject(cam, corners[i], ox, oy) orelse continue;
            const pb = z3d.ovProject(cam, corners[(i + 1) % 4], ox, oy) orelse continue;
            z3d.overlayLine(pa[0], pa[1], pb[0], pb[1], col[0], col[1], col[2], 1.5);
        }
    }
}

/// Gold when this axis is the live grab — the studio glows BOTH ends of a grabbed axis.
pub fn gizmoAxisDrawColor(axis: i32) [3]f32 {
    if (z3d.g_gizmo_active == axis or z3d.g_gizmo_active == axis + z3d.GIZMO_NEG_BASE) return z3d.GIZMO_ACTIVE;
    return z3d.axisColor(axis);
}
/// Chevron arrowhead (studio ArrowHead): two wings opening back along the axis at ±26°,
/// so MOVE reads as an arrow (vs SCALE's square).
pub fn drawGizmoArrowHead(x: f32, y: f32, dx: f32, dy: f32, col: [3]f32) void {
    const base = std.math.atan2(dy, dx);
    const wing = 26.0 * std.math.pi / 180.0;
    const len = z3d.GIZMO_HEAD_PX + 3;
    z3d.overlayLine(x, y, x - @cos(base - wing) * len, y - @sin(base - wing) * len, col[0], col[1], col[2], z3d.GIZMO_SHAFT_W);
    z3d.overlayLine(x, y, x - @cos(base + wing) * len, y - @sin(base + wing) * len, col[0], col[1], col[2], z3d.GIZMO_SHAFT_W);
}
/// Square scale handle (studio Square): screen-aligned quad, dark edge under the fill.
pub fn drawGizmoSquare(x: f32, y: f32, col: [3]f32) void {
    const h = z3d.GIZMO_HEAD_PX;
    const e = h + 1.5;
    core.drawTri(x - e, y - e, x + e, y - e, x + e, y + e, z3d.GIZMO_DARK[0], z3d.GIZMO_DARK[1], z3d.GIZMO_DARK[2], 1.0);
    core.drawTri(x - e, y - e, x + e, y + e, x - e, y + e, z3d.GIZMO_DARK[0], z3d.GIZMO_DARK[1], z3d.GIZMO_DARK[2], 1.0);
    core.drawTri(x - h, y - h, x + h, y - h, x + h, y + h, col[0], col[1], col[2], 1.0);
    core.drawTri(x - h, y - h, x + h, y + h, x - h, y + h, col[0], col[1], col[2], 1.0);
}
pub fn drawGizmoOverlay(cam: model_paint.Camera, ox: f32, oy: f32) void {
    if (z3d.g_paint_session) return; // paint mode suspends the gizmo entirely (req_2662)
    if (z3d.meshEditModeRaw() == 0) return;
    const pivot = mesh_edit.selectionPivot() orelse return;
    const pc = model_paint.project(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, pivot) orelse return;
    if (z3d.g_gizmo_tool == .rotate) {
        var axis: i32 = 0;
        while (axis < 3) : (axis += 1) z3d.drawGizmoRing(cam, pivot, axis, ox, oy);
        // rotate hub: the studio's small light dot at the anchor.
        z3d.overlayDot(pc[0] + ox, pc[1] + oy, z3d.GIZMO_HUB_RIM[0], z3d.GIZMO_HUB_RIM[1], z3d.GIZMO_HUB_RIM[2], 6);
    } else {
        // Arms in the current capsule pass; MOVE tips get chevrons. An axis aimed at
        // the camera draws nothing — see gizmoAxisGrabbable.
        const face_on = z3d.gizmoFaceOnPxPerUnit(cam, pivot);
        var axis: i32 = 0;
        while (axis < 3) : (axis += 1) {
            const s = z3d.axisScreenInfo(cam, pivot, z3d.axisVec(axis)) orelse continue;
            if (!z3d.gizmoAxisGrabbable(s, face_on)) continue;
            const c = z3d.gizmoAxisDrawColor(axis);
            const signs = [2]f32{ 1, -1 };
            const nsigns: usize = if (z3d.g_gizmo_tool == .scale) 2 else 1; // scale is double-ended
            var k: usize = 0;
            while (k < nsigns) : (k += 1) {
                const h = z3d.gizmoArmEnd(s, signs[k]);
                z3d.overlayLine(s.ax + ox, s.ay + oy, h[0] + ox, h[1] + oy, c[0], c[1], c[2], z3d.GIZMO_SHAFT_W);
                if (z3d.g_gizmo_tool == .move) z3d.drawGizmoArrowHead(h[0] + ox, h[1] + oy, s.dx, s.dy, c);
            }
        }
        // Fresh segment: the square handles are POLYS, and within one segment polys flush
        // under capsules — the break lands them ON TOP of the already-flushed arms, and
        // the hub capsules below then top the squares (studio stacking: arm < square < hub).
        z3d.overlayLayerBreak(ox, oy);
        if (z3d.g_gizmo_tool == .scale) {
            var sq_axis: i32 = 0;
            while (sq_axis < 3) : (sq_axis += 1) {
                const s = z3d.axisScreenInfo(cam, pivot, z3d.axisVec(sq_axis)) orelse continue;
                if (!z3d.gizmoAxisGrabbable(s, face_on)) continue;
                const c = z3d.gizmoAxisDrawColor(sq_axis);
                for ([2]f32{ 1, -1 }) |sign| {
                    const h = z3d.gizmoArmEnd(s, sign);
                    z3d.drawGizmoSquare(h[0] + ox, h[1] + oy, c);
                }
            }
        }
        // Hub (studio): MOVE = hollow ring, decoration; SCALE = solid ball, THE uniform
        // handle — grabbing it scales all three axes at once, gold while held.
        const hub_active = z3d.g_gizmo_active == z3d.GIZMO_UNIFORM_CODE;
        const rim = if (hub_active) z3d.GIZMO_ACTIVE else z3d.GIZMO_HUB_RIM;
        z3d.overlayDot(pc[0] + ox, pc[1] + oy, rim[0], rim[1], rim[2], z3d.GIZMO_CENTER_PX * 2 + 2);
        const core_col = if (z3d.g_gizmo_tool == .scale) (if (hub_active) z3d.GIZMO_ACTIVE else z3d.GIZMO_HUB_FILL) else z3d.GIZMO_DARK;
        core.drawCapsule(pc[0] + ox, pc[1] + oy, pc[0] + ox, pc[1] + oy, core_col[0], core_col[1], core_col[2], 1.0, z3d.GIZMO_CENTER_PX * 2 - 2);
    }
    // Vertex-snap lock (req_3378): the target vertex the held-V drag is flush
    // against, marked gold — the same active color as the grabbed handle.
    if (z3d.g_gizmo_snap_marker) |v| {
        if (model_paint.project(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, v)) |mp| {
            z3d.overlayDot(mp[0] + ox, mp[1] + oy, z3d.GIZMO_ACTIVE[0], z3d.GIZMO_ACTIVE[1], z3d.GIZMO_ACTIVE[2], 7);
        }
    }
    // Live step readout (req_2759): the drag's current SNAPPED value beside the pivot —
    // "+3.00u" / "+15°" / "×1.20" — so the grid the drag clicks along can be read off.
    if (z3d.g_gizmo_readout_len > 0) {
        const line = z3d.g_gizmo_readout[0..z3d.g_gizmo_readout_len];
        const tx = pc[0] + ox + 16;
        const ty = pc[1] + oy - 22;
        core.drawTextLine(line, tx + 1, ty + 1, 12, 0.02, 0.03, 0.07, 0.9); // shadow
        core.drawTextLine(line, tx, ty, 12, z3d.OV_ORANGE[0], z3d.OV_ORANGE[1], z3d.OV_ORANGE[2], 1.0);
    }
}

/// Port of the studio's pickGizmoHandle: rotate → nearest ring; else the SCALE hub
/// (uniform, centerPx+4 grab ring) first, then each arm — TIP or SHAFT, whichever is
/// closer, within grabPx. Returns 0..2 = positive axis handle, GIZMO_NEG_BASE+axis =
/// scale's negative-end square, GIZMO_UNIFORM_CODE = the uniform hub, -1 = miss.
pub fn meshGizmoHit(mx: f32, my: f32) i32 {
    if (z3d.g_paint_session) return -1; // req_2662: no gizmo grabs while paint owns the surface
    if (!z3d.g_me_capture or z3d.meshEditModeRaw() == 0 or !model_paint.hasTarget()) return -1;
    const pivot = mesh_edit.selectionPivot() orelse return -1;
    const cam = model_paint.Camera{ .eye = z3d.g_paint_eye, .target = z3d.g_paint_target, .fov_deg = z3d.g_paint_fov };
    const lmx = z3d.vpLocalX(mx);
    const lmy = z3d.vpLocalY(my);
    var best: i32 = -1;
    var best_d2: f32 = z3d.GIZMO_HIT_PX * z3d.GIZMO_HIT_PX;
    if (z3d.g_gizmo_tool == .rotate) {
        var axis: i32 = 0;
        while (axis < 3) : (axis += 1) {
            const d2 = z3d.ringHitDist2(cam, pivot, axis, lmx, lmy);
            if (d2 < best_d2) {
                best_d2 = d2;
                best = axis;
            }
        }
        return best;
    }
    const a = model_paint.project(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, pivot) orelse return -1;
    if (z3d.g_gizmo_tool == .scale) {
        const dxc = lmx - a[0];
        const dyc = lmy - a[1];
        const r = z3d.GIZMO_CENTER_PX + 4;
        if (dxc * dxc + dyc * dyc <= r * r) return z3d.GIZMO_UNIFORM_CODE;
    }
    const face_on = z3d.gizmoFaceOnPxPerUnit(cam, pivot);
    var axis: i32 = 0;
    while (axis < 3) : (axis += 1) {
        const s = z3d.axisScreenInfo(cam, pivot, z3d.axisVec(axis)) orelse continue;
        if (!z3d.gizmoAxisGrabbable(s, face_on)) continue; // no arm drawn → no grab
        const signs = [2]f32{ 1, -1 };
        const nsigns: usize = if (z3d.g_gizmo_tool == .scale) 2 else 1;
        var k: usize = 0;
        while (k < nsigns) : (k += 1) {
            const h = z3d.gizmoArmEnd(s, signs[k]);
            const tdx = lmx - h[0];
            const tdy = lmy - h[1];
            const d2 = @min(tdx * tdx + tdy * tdy, z3d.segDist2(lmx, lmy, s.ax, s.ay, h[0], h[1]));
            if (d2 < best_d2) {
                best_d2 = d2;
                best = if (k == 1) axis + z3d.GIZMO_NEG_BASE else axis;
            }
        }
    }
    return best;
}

/// Begin/update the session at the backdrop's center (`__model_bd_gizmo_set`).
pub fn bdGizmoSet(x: f32, y: f32, z: f32) void {
    z3d.g_bd_pos = .{ x, y, z };
}
/// End the session (`__model_bd_gizmo_clear`) — panel closed / row collapsed.
pub fn bdGizmoClear() void {
    z3d.g_bd_pos = null;
    z3d.g_bd_active = -1;
}
pub fn bdGizmoActive() bool {
    return z3d.g_bd_pos != null;
}
pub fn bdGizmoPos() [3]f32 {
    return z3d.g_bd_pos orelse .{ 0, 0, 0 };
}
/// Hit-test the session's three move arms (tip or shaft, grabPx — the mesh gizmo's
/// exact rule). Returns the axis 0..2, or -1.
pub fn bdGizmoHit(mx: f32, my: f32) i32 {
    const pos = z3d.g_bd_pos orelse return -1;
    if (z3d.g_paint_session or !z3d.g_me_capture or !model_paint.hasTarget()) return -1;
    const cam = model_paint.Camera{ .eye = z3d.g_paint_eye, .target = z3d.g_paint_target, .fov_deg = z3d.g_paint_fov };
    const lmx = z3d.vpLocalX(mx);
    const lmy = z3d.vpLocalY(my);
    var best: i32 = -1;
    var best_d2: f32 = z3d.GIZMO_HIT_PX * z3d.GIZMO_HIT_PX;
    const face_on = z3d.gizmoFaceOnPxPerUnit(cam, pos);
    var axis: i32 = 0;
    while (axis < 3) : (axis += 1) {
        const s = z3d.axisScreenInfo(cam, pos, z3d.axisVec(axis)) orelse continue;
        if (!z3d.gizmoAxisGrabbable(s, face_on)) continue; // no arm drawn → no grab
        const h = z3d.gizmoArmEnd(s, 1);
        const tdx = lmx - h[0];
        const tdy = lmy - h[1];
        const d2 = @min(tdx * tdx + tdy * tdy, z3d.segDist2(lmx, lmy, s.ax, s.ay, h[0], h[1]));
        if (d2 < best_d2) {
            best_d2 = d2;
            best = axis;
        }
    }
    return best;
}
pub fn bdGizmoBegin(code: i32) void {
    z3d.g_bd_active = code;
    z3d.g_bd_raw = 0;
    z3d.g_bd_applied = 0;
    z3d.g_bd_pos0 = z3d.g_bd_pos orelse .{ 0, 0, 0 };
}
/// Drag the grabbed arm — the mesh move-gizmo's exact stepped mapping (whole modeling
/// units, Shift = fine grid, Ctrl/Alt = freeform), applied to the session pose.
pub fn bdGizmoDrag(dx: f32, dy: f32, shift: bool, free: bool) bool {
    if (z3d.g_bd_pos == null or z3d.g_bd_active < 0 or z3d.g_bd_active > 2) return false;
    const cam = model_paint.Camera{ .eye = z3d.g_paint_eye, .target = z3d.g_paint_target, .fov_deg = z3d.g_paint_fov };
    const s = z3d.axisScreenInfo(cam, z3d.g_bd_pos0, z3d.axisVec(z3d.g_bd_active)) orelse return false;
    // Same bounded mapping as the mesh move gizmo (req_4160/4161).
    z3d.g_bd_raw += (dx * s.dx + dy * s.dy) * gizmo_axis_map.worldPerPx(s, z3d.gizmoFaceOnPxPerUnit(cam, z3d.g_bd_pos0));
    const target = z3d.snapStep(z3d.g_bd_raw, z3d.GIZMO_STEP_M, z3d.GIZMO_STEP_FINE_M, shift, free);
    const d = target - z3d.g_bd_applied;
    if (@abs(d) < 1e-7) return false;
    const av = z3d.axisVec(z3d.g_bd_active);
    z3d.g_bd_pos = z3d.vadd(z3d.g_bd_pos0, z3d.vmul(av, target));
    z3d.g_bd_applied = target;
    return true;
}
pub fn bdGizmoFinish() void {
    z3d.g_bd_active = -1;
}
/// The session's move arms + hub, drawn beside the mesh dressing — same anatomy as the
/// mesh MOVE gizmo (arm/chevron/hollow hub) so it reads as "the gizmo, on the image".
pub fn drawBdGizmoOverlay(cam: model_paint.Camera, ox: f32, oy: f32) void {
    const pos = z3d.g_bd_pos orelse return;
    if (z3d.g_paint_session) return;
    const pc = model_paint.project(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, pos) orelse return;
    const face_on = z3d.gizmoFaceOnPxPerUnit(cam, pos);
    var axis: i32 = 0;
    while (axis < 3) : (axis += 1) {
        const s = z3d.axisScreenInfo(cam, pos, z3d.axisVec(axis)) orelse continue;
        if (!z3d.gizmoAxisGrabbable(s, face_on)) continue;
        const col = if (z3d.g_bd_active == axis) z3d.GIZMO_ACTIVE else z3d.axisColor(axis);
        const h = z3d.gizmoArmEnd(s, 1);
        z3d.overlayLine(s.ax + ox, s.ay + oy, h[0] + ox, h[1] + oy, col[0], col[1], col[2], z3d.GIZMO_SHAFT_W);
        z3d.drawGizmoArrowHead(h[0] + ox, h[1] + oy, s.dx, s.dy, col);
    }
    z3d.overlayDot(pc[0] + ox, pc[1] + oy, z3d.GIZMO_HUB_RIM[0], z3d.GIZMO_HUB_RIM[1], z3d.GIZMO_HUB_RIM[2], z3d.GIZMO_CENTER_PX * 2 + 2);
    core.drawCapsule(pc[0] + ox, pc[1] + oy, pc[0] + ox, pc[1] + oy, z3d.GIZMO_DARK[0], z3d.GIZMO_DARK[1], z3d.GIZMO_DARK[2], 1.0, z3d.GIZMO_CENTER_PX * 2 - 2);
}
